// Plain const data classes for the non-block/item registries of Create.
// Pure Dart, no imports. Populated by registries.g.dart (generated by
// tool/extract_registries.dart).
//
// Conventions
//  * `key` is always the path part of the `create:` id (no namespace).
//  * `javaClass` is a fully qualified Java class name (nested classes use `.`).
//  * `verified: false` marks entries where part of the data could not be
//    derived with certainty from the Java sources (see REPORT_registries.md).

/// A BlockEntityType registered by `AllBlockEntityTypes`.
class BlockEntityTypeDef {
  const BlockEntityTypeDef({
    required this.key,
    required this.javaClass,
    required this.validBlocks,
    this.validBlocksSource = '',
    this.displaySource,
    this.displayTarget,
    this.hasVisual = false,
    this.hasRenderer = false,
    this.verified = true,
  });

  final String key;

  /// Fully qualified class of the BlockEntity (factory `X::new`).
  final String javaClass;

  /// Block keys (path of `create:<key>`) that may carry this block entity,
  /// in the order the Java code lists them (dyed lists in DyeColor order).
  final List<String> validBlocks;

  /// The original Java expression(s) the list was derived from.
  final String validBlocksSource;

  /// Display link source/target registry key bound to the block entity type.
  final String? displaySource;
  final String? displayTarget;

  /// Client-only information, kept for completeness.
  final bool hasVisual;
  final bool hasRenderer;
  final bool verified;
}

/// An EntityType registered by `AllEntityTypes`.
class EntityTypeDef {
  const EntityTypeDef({
    required this.key,
    required this.javaClass,
    required this.category,
    required this.width,
    required this.height,
    required this.eyeHeight,
    required this.trackingRange,
    required this.updateInterval,
    required this.sendVelocity,
    required this.fireImmune,
    required this.summonable,
    required this.complexSpawnData,
    this.superClass = '',
    this.dimensionsDefaulted = false,
    this.teleportingNotSupportedTag = false,
    this.verified = true,
  });

  final String key;
  final String javaClass;
  final String superClass;

  /// MobCategory name (`MISC`, ...).
  final String category;
  final double width;
  final double height;

  /// Eye height. When the Java code does not call `eyeHeight(..)` vanilla
  /// derives it as `height * 0.85` (that is what is stored here).
  final double eyeHeight;
  final int trackingRange;
  final int updateInterval;
  final bool sendVelocity;
  final bool fireImmune;
  final bool summonable;

  /// True when the entity class implements `IEntityWithComplexSpawn` (extra
  /// spawn payload written with writeSpawnData).
  final bool complexSpawnData;

  /// True when width/height are the vanilla builder defaults (0.6 x 1.8)
  /// because the `build` hook never calls `sized`.
  final bool dimensionsDefaulted;

  /// `minecraft:teleporting_not_supported` entity type tag membership.
  final bool teleportingNotSupportedTag;
  final bool verified;
}

class MenuTypeDef {
  const MenuTypeDef({
    required this.key,
    required this.menuClass,
    this.screenClass = '',
    this.factory = 'ForgeMenuFactory',
    this.verified = true,
  });

  final String key;
  final String menuClass;
  final String screenClass;

  /// `ForgeMenuFactory` => menu is created with extra (buffer) data.
  final String factory;
  final bool verified;
}

class DataComponentDef {
  const DataComponentDef({
    required this.key,
    required this.javaType,
    required this.persistent,
    required this.networkSynced,
    required this.persistentCodec,
    required this.networkCodec,
    this.codecJavaClass = '',
    this.codecField = '',
    this.codecSourceFile = '',
    this.codecDescription = '',
    this.valueShape = '',
    this.deprecated = false,
    this.verified = true,
  });

  final String key;

  /// Generic argument of `DataComponentType<T>` as written in Java.
  final String javaType;
  final bool persistent;
  final bool networkSynced;

  /// The Java expressions passed to `persistent(..)` / `networkSynchronized(..)`.
  final String persistentCodec;
  final String networkCodec;

  /// Fully qualified class that owns the persistent codec field (empty when
  /// the codec is a vanilla/library expression such as `Codec.BOOL`).
  final String codecJavaClass;
  final String codecField;

  /// Path of the Java file relative to the mod source root.
  final String codecSourceFile;

  /// Whitespace-normalised initializer text of the codec field, i.e. the
  /// textual description of the codec structure.
  final String codecDescription;

  /// Record components / shape of the value class when known.
  final String valueShape;
  final bool deprecated;
  final bool verified;
}

class FluidDef {
  const FluidDef({
    required this.key,
    required this.kind,
    required this.sourceKey,
    required this.flowingKey,
    this.bucketKey,
    this.blockKey,
    this.fluidTypeKey = '',
    this.lang = '',
    this.sourceClass = '',
    this.flowingClass = '',
    this.fluidTypeClass = '',
    this.attributes = const {},
    this.verified = true,
  });

  final String key;

  /// `virtual` (no bucket/block) or `standard`.
  final String kind;
  final String sourceKey;
  final String flowingKey;
  final String? bucketKey;
  final String? blockKey;
  final String fluidTypeKey;
  final String lang;
  final String sourceClass;
  final String flowingClass;
  final String fluidTypeClass;

  /// Free-form attributes: viscosity, density, levelDecreasePerBlock,
  /// tickRate, slopeFindDistance, explosionResistance, mapColor, fogColor,
  /// transparency, tags, etc. Values are strings (numbers in Java syntax).
  final Map<String, String> attributes;
  final bool verified;
}

class RecipeTypeDef {
  const RecipeTypeDef({
    required this.key,
    required this.enumName,
    required this.recipeClass,
    required this.serializerSummary,
    required this.registersRecipeType,
    this.vanillaRecipeType = '',
    this.processing = false,
    this.maxItemInputs,
    this.maxItemOutputs,
    this.maxFluidInputs,
    this.maxFluidOutputs,
    this.canRequireHeat,
    this.canSpecifyDuration,
    this.inputSummary = '',
    this.outputSummary = '',
    this.generatedRecipeCount = 0,
    this.verified = true,
  });

  /// Serializer key == recipe type key (path of `create:<key>`).
  final String key;
  final String enumName;
  final String recipeClass;
  final String serializerSummary;

  /// False for `TOOLBOX_DYEING` / `ITEM_COPYING` (crafting special recipes
  /// that reuse `minecraft:crafting`).
  final bool registersRecipeType;
  final String vanillaRecipeType;
  final bool processing;
  final int? maxItemInputs;
  final int? maxItemOutputs;
  final int? maxFluidInputs;
  final int? maxFluidOutputs;
  final bool? canRequireHeat;
  final bool? canSpecifyDuration;
  final String inputSummary;
  final String outputSummary;

  /// Number of recipe json files of that type under data/create/recipe.
  final int generatedRecipeCount;
  final bool verified;
}

