class WrappedSoundDef {
  const WrappedSoundDef({
    required this.javaEvent,
    required this.volume,
    required this.pitch,
  });

  /// Java expression of the vanilla sound event, e.g. `SoundEvents.ANVIL_LAND`.
  final String javaEvent;
  final double volume;
  final double pitch;
}

class SoundEventDef {
  const SoundEventDef({
    required this.key,
    required this.javaConstant,
    required this.kind,
    required this.registeredEvents,
    this.subtitle,
    this.category = 'BLOCKS',
    this.attenuationDistance = 0,
    this.wrapped = const [],
    this.variants = const [],
    this.soundsJson = const {},
    this.verified = true,
  });

  /// Main sound event key.
  final String key;
  final String javaConstant;

  /// `custom` (ogg files, `variants` are extra files) or `wrapped` (plays
  /// one or more vanilla events; sub events `<key>_compounded_<i>`).
  final String kind;

  /// Every `create:<x>` SoundEvent registered for the entry (main event
  /// first, then compounded sub events).
  final List<String> registeredEvents;
  final String? subtitle;
  final String category;
  final int attenuationDistance;
  final List<WrappedSoundDef> wrapped;
  final List<String> variants;

  /// Raw `assets/create/sounds.json` object (as JSON text) per registered
  /// event key.
  final Map<String, String> soundsJson;
  final bool verified;
}

