    this.javaConstant = '',
    this.verified = true,
  });

  /// Path part of the advancement id, e.g. `andesite_alloy` or
  /// `recipes/misc/crafting/kinetics/foo`.
  final String id;

  /// `create` (Create's own advancement tree) or `recipe` (recipe unlock).
  final String kind;
  final String? parent;

  /// Criterion trigger ids used.
  final List<String> trigger;
  final String? title;
  final String? description;

  /// SILENT/NORMAL/NOISY/EXPERT/SECRET.
