class CreativeTabDef {
  const CreativeTabDef({
    required this.key,
    required this.titleKey,
    required this.iconBlockOrItem,
    this.tabsBefore = const [],
    this.includesItems = false,
    this.excluded = const [],
    this.searchOnly = const [],
    this.orderings = const [],
    this.stackComponents = const {},
    this.contentSources = '',
    this.contentOrder = const [],
    this.contentOrderComplete = false,
    this.verified = true,
  });

  final String key;
  final String titleKey;

  /// Registry key of the icon block/item (`create:cogwheel`).
  final String iconBlockOrItem;

  /// Vanilla/other tab keys this tab is placed after.
  final List<String> tabsBefore;

  /// Whether non-block items are added (BASE tab: yes; palettes: no).
  final bool includesItems;

  /// Item keys never shown (static part of the exclusion list).
  final List<String> excluded;

  /// Item keys only visible in the search tab.
  final List<String> searchOnly;
  final List<CreativeTabItemOrderingDef> orderings;

  /// item key -> component description for the displayed stack.
  final Map<String, String> stackComponents;

  /// Prose description of which registrations feed the tab.
  final String contentSources;

  /// Item keys in display order where derivable (see REPORT).
  final List<String> contentOrder;
  final bool contentOrderComplete;
  final bool verified;
}

/// Top-level container with everything, in registration order.
class RegistriesManifest {
  const RegistriesManifest({
    required this.blockEntityTypes,
    required this.entityTypes,
    required this.menuTypes,
    required this.dataComponents,
    required this.fluids,
    required this.recipeTypes,
    required this.damageTypes,
    required this.enchantments,
    required this.soundEvents,
    required this.particleTypes,
    required this.entityDataSerializers,
    required this.mapDecorations,
    required this.advancements,
    required this.triggers,
    required this.customRegistries,
    required this.potatoProjectileTypes,
    required this.creativeTabs,
  });

  final List<BlockEntityTypeDef> blockEntityTypes;
  final List<EntityTypeDef> entityTypes;
  final List<MenuTypeDef> menuTypes;
  final List<DataComponentDef> dataComponents;
  final List<FluidDef> fluids;
  final List<RecipeTypeDef> recipeTypes;
  final List<DamageTypeDef> damageTypes;
  final List<EnchantmentDef> enchantments;
  final List<SoundEventDef> soundEvents;
  final List<ParticleTypeDef> particleTypes;
  final List<EntityDataSerializerDef> entityDataSerializers;
  final List<MapDecorationDef> mapDecorations;
  final List<AdvancementDef> advancements;
  final List<TriggerDef> triggers;
  final List<CustomRegistryDef> customRegistries;
  final List<PotatoProjectileTypeDef> potatoProjectileTypes;
  final List<CreativeTabDef> creativeTabs;
}
